import React, { memo } from "react";
import { useTranslation } from "react-i18next";
import { useNavigate } from 'react-router-dom';
import { useSelector } from "react-redux";
import { selectIsAuthenticated } from "../../../features/slices/authSlice";
import Swal from "sweetalert2";
import { resolveI18n } from "../../../utils/resolveI18n";

const ProductCard = memo(({ product }) => {
  const { i18n } = useTranslation();
  const navigate = useNavigate();
  const isAuthenticated = useSelector(selectIsAuthenticated);
  const name = resolveI18n(product?.name, i18n.language);
  const description = resolveI18n(product?.description, i18n.language);

  const handleBuyNow = (e) => {
    e.stopPropagation();
    if (!isAuthenticated) {
      Swal.fire({
        title: "Login Required",
        text: "You must log in to purchase this product.",
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: "#3085d6",
        cancelButtonColor: "#d33",
        confirmButtonText: "Login",
      }).then((result) => {
        if (result.isConfirmed) {
          navigate("/login");
        }
      });
      return;
    }
    navigate('/checkout', { state: { product, quantity: 1 } });
  };

  const handleDetailsClick = (e) => {
    e.stopPropagation();
    navigate(`/webshop/${product.id}`);
  };

  return (
    <div className="bg-white rounded-xl overflow-hidden border border-green-400 shadow-sm p-3 flex flex-col h-full">
      {/* Image Container with Inset padding and border */}
      <div className="relative aspect-square mb-4 rounded-lg overflow-hidden border border-gray-100">
        <img
          src={product.image}
          alt={name}
          className="w-full h-full object-cover transition-transform duration-500 hover:scale-105"
        />
      </div>

      {/* Product Details */}
      <div className="flex flex-col grow px-1">
        <h3 className="text-2xl font-semibold text-gray-800 mb-2  leading-tight">
          {name}
        </h3>

        <p className="text-base h-12 text-gray-600 mb-4 line-clamp-3 leading-relaxed">
          {description}
        </p>

        <div className="text-2xl font-semibold text-gray-900 mb-4 ">
          €{parseFloat(product.price || 0).toFixed(2)}
        </div>

        {/* Action Buttons */}
        <div className="flex gap-2 mt-auto pb-1">
          <button onClick={handleBuyNow} className="flex-1 bg-green-500/60  text-white text-base  py-2.5 rounded-lg">
            Buy Now
          </button>

          <button className="flex-1 border border-[#6E35AE]  text-[#6E35AE] text-base  py-2.5 rounded-lg" onClick={handleDetailsClick}>
            Details
          </button>
        </div>
      </div>
    </div>
  );
});

ProductCard.displayName = "ProductCard";

export default ProductCard;
